def run(jobs, workers, strict=False, drop=False):
    def fits(cap):
        used, load = 1, 0
        for j in jobs:
            if load + j > cap:
                used += 1
                load = 0 if drop else j
            else:
                load += j
        return used < workers if strict else used <= workers
    lo, hi, rounds = max(jobs), sum(jobs), 0
    while lo < hi:
        mid = (lo + hi) // 2
        rounds += 1
        if fits(mid): hi = mid
        else: lo = mid + 1
    return lo, rounds
jobs = [10, 10, 12, 9, 7, 4, 12, 5]
print(run(jobs, 3), run(jobs, 3, strict=True), run(jobs, 3, drop=True))   # (28, 6) (37, 6) (20, 6)
